namespace ghidra.app.cmd.function;

using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util.exception;
using ghidra.util.exception;

/**
 * Command to rename a stack variable.
 */
public class SetVariableNameCmd : Command<Program> {

	private Address fnEntry;
	private string varName;
	private string newName;
	private SourceType source;

	private bool isParm;
	private string status;

	/**
	 * Constructs a new command to rename a stack/reg variable.
	 * @param var variable to rename
	 * @param newName the new name to give to the stack variable.
	 * @param source the source of this variable name
	 */
	public SetVariableNameCmd(Variable var, string newName, SourceType source) {
		this.fnEntry = var.getFunction().getEntryPoint();
		this.varName = var.getName();
		this.newName = newName;
		this.source = source;
	}

	/**
	 * Constructs a new command to rename a stack/reg variable.
	 * @param fnEntry
	 * @param varName
	 * @param newName
	 * @param source
	 */
	public SetVariableNameCmd(Address fnEntry, string varName, string newName, SourceType source) {
		this.fnEntry = fnEntry;
		this.varName = varName;
		this.newName = newName;
		this.source = source;
	}

	/* @Override */
	public bool applyTo(Program program) {

		Function f = program.getFunctionManager().getFunctionAt(fnEntry);
		if (f == null) {
			status = "Function not found";
			return false;
		}

		Symbol s = program.getSymbolTable().getParameterSymbol(varName, f);
		if (s == null) {
			s = program.getSymbolTable().getLocalVariableSymbol(varName, f);
		}
		if (s == null) {
			status = "Variable not found";
			return false;
		}

		Variable var = (Variable) s.getObject();
		isParm = var is Parameter;
		try {
			var.setName(newName, source);
			return true;
		}
		catch (DuplicateNameException e) {
			status = e.getMessage();
		}
		catch (InvalidInputException e) {
			status = e.getMessage();
		}
		return false;
	}

	/* @Override */
	public string getStatusMsg() {
		return status;
	}

	/* @Override */
	public string getName() {
		return "Rename " + (isParm ? "Parameter" : "Variable");
	}

}
